import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { PmoaService } from 'src/app/services/emis/pmoa.services';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import moment from 'moment';
@Component({
  selector: 'app-student-list',
  templateUrl: './student-list.page.html',
  styleUrls: ['./student-list.page.scss'],
})
export class StudentListPage implements OnInit {

  class_studying_id: any;
  class_section: any;
  SchoolId: any;

  StudentData: any[] = [];
  searchData: any[] = [];
  StudentListData: any[] = [];

  searchTerm: any;

  totalStudent: number;
  totalDoctor: number;
  totalTeacher: any;

  sclid: any;
  filterDatByTeacher: any;
  filterDatByDoctor: any[];

  totalStudentData: any;
  totalDataScreen: any;
  dataForm: string;
  totalSchool: any;
  totalScnTech: any;
  totalrefPmoa: any;
  totalscnPmoa: any;
  sessionUserName: any;
  AddStudents: any = [];
  sdntList: any = '';
  constructor(
    private router: Router,
    private pmoaService: PmoaService,
    private route: ActivatedRoute,
    private sqliteDB: SqlitedatabaseService,
    private usersessionService: UserSessionService,
    private alertService: AlertService,
  ) { }

  ngOnInit() {
  }

  ionViewDidEnter() {

    this.sessionUserName = this.usersessionService.emis_username();


    if (this.route.snapshot.queryParamMap.get("class_studying_id")) {
      this.class_studying_id = this.route.snapshot.queryParamMap.get("class_studying_id");
      this.class_section = this.route.snapshot.queryParamMap.get("class_section");
      this.SchoolId = this.route.snapshot.queryParamMap.get("SchoolId");
      this.dataForm = this.route.snapshot.queryParamMap.get("data");
    }

    this.totalStudent = 0
    this.totalTeacher = 0
    this.totalDoctor = 0

    this.StudentData = [];

    this.getTotalCount();
    this.sdntList = '';
    this.AddStudents = [];
    this.searchData = [];
    debugger
    // if (this.dataForm == 'added') {
    //   this.getStudentLocalDB();
    // } else {
      // this.onSync();
    // };
    this.getstudentData();
  } 

 

  getAddStudentsList() {
    this.pmoaService.getPmoaAddNewStudents(this.SchoolId, this.class_studying_id, this.class_section).subscribe((response) => {
      if (response.dataStatus) {
        this.AddStudents = [];
        for (var i = 0; i < this.searchData.length; i++) {
          let sdntId = this.searchData[i].student_id

          var index = response.result.findIndex(function (o) {
            return o.student_id == sdntId;
          })
          if (index !== -1) response.result.splice(index, 1);
        }
        debugger
        this.AddStudents = response.result;
        this.sdntList = '';
      } 
    })
  }

  // Check Local Data Exist Method_________________________________________________________________________________*
  checkLocalExistStudentList() {
    // this.sqliteDB.checkDataExistsWithConditions('Studentlist', "SchoolId", this.SchoolId).then((res) => {
    //   if (res == true) {
    //     this.getStudentLocalDB(); // Local Data
    //   }
    //   else {
    //     this.getstudentData();  // From Server
    //   }
    // });
    this.getstudentData();  
  }

  getStudentLocalDB() {
    let query = 'SELECT UserId as student_id, Name as name,Status as HealthSts FROM Studentlist' +
      ' WHERE SchoolId = "' + this.SchoolId + '"' +
      ' And Classstudyingid = "' + this.class_studying_id + '"' +
      ' And ClassSection = "' + this.class_section + '"';
    return this.sqliteDB.getDataLocalDB(query).then(data => {
      if (data.rows.length > 0) {
        this.StudentData = [];
        this.searchData = [];
        this.totalStudent = 0;
        this.sclid = [];
        for (var i = 0; i < data.rows.length; i++) {
          this.searchData.push(data.rows.item(i));
          this.StudentData.push(data.rows.item(i));
        }

        this.sclid = this.SchoolId
        this.filterDatByTeacher = this.StudentData.filter(
          (item: any) => item.Status === "2"
        );
        this.filterDatByDoctor = this.StudentData.filter(
          (item: any) => item.Status === "1"
        );
 
        this.totalStudent = this.StudentData.length
        this.totalDoctor = this.filterDatByDoctor.length
        this.totalTeacher = this.filterDatByTeacher.length;
        this.getAddStudentsList();
      } else {
        this.getstudentData();
      }
    });
  }

  getTotalCount() {
    this.pmoaService.getSchoolCountData(this.SchoolId, this.class_studying_id, this.class_section).subscribe((response) => {
      if (response.dataStatus == true) {
        this.totalSchool = response.result.TotStuCountClsSec[0].Count
        this.totalScnTech = response.result.TotStuScrndCountClsSec[0].Count
        this.totalrefPmoa = response.result.TotStuRefrdPmoaClsSec[0].Count
        this.totalscnPmoa = response.result.TotStuScrndByPmoaClsSec[0].Count
      }
    })
  }

  getstudentData() {
    this.StudentData = []
    this.searchData = []
    this.StudentListData = []
    this.sclid = this.SchoolId
    this.pmoaService.getTotalStudentData(this.SchoolId, this.class_section, this.class_studying_id).subscribe((response) => {
      if (response.dataStatus) {
         response.result.map((item) => {
          // let data = {
          //   "student_id": item.student_id,
          //   "name": item.name,
          //   "HealthSts": item.HealthSts,
          //   UserId:item.UserId
          // }
          this.StudentData.push(item);
          this.searchData.push(item);
          this.StudentListData.push(item);
        })
        // this.StudentListData.forEach(key => {
        //   this.saveStudentLocalDB(key);
        // });
        // this.getStudentLocalDB();  
      } else {
        this.alertService.error(response.message);
      }
      this.getAddStudentsList();
    })
  }

  getFilterItems(event) {
    this.searchData = [];
    this.searchTerm = event.detail.value.trim();
    this.searchData = this.StudentData.filter((item) => {
      return item.name.toLowerCase().indexOf(this.searchTerm.toLowerCase()) > -1;
    });
  }

  questionsPage(student_id, name, SchoolId, data) {
    this.router.navigate(['/tabs/pmoa-questions'], {
      queryParams: { student_id, name, SchoolId, "class_studying_id": this.class_studying_id, "class_section": this.class_section,
      UserId:data.UserId,SpecsId:data.SpecsId,SpecsStatus:data.SpecsStatus,pmoa:data.pmoa }
      
    });
  }

  navigateBack() {
    this.router.navigate(['/tabs/section-list']);
  }

  saveStudentLocalDB(element) {
    const datainsert = 'INSERT INTO Studentlist VALUES (?,?,?,?,?,?,?)';
    this.sqliteDB.insert(datainsert, [null, element.student_id, element.name, element.HealthSts, this.class_studying_id, this.class_section, this.SchoolId]).then(insertres => {
      console.log('blockListData inserted successfully', insertres)
      if (insertres) {
      }
    });
  }

  onSync() { 
    // let query = 'DELETE FROM Studentlist' +
    // ' WHERE SchoolId = "' + this.SchoolId + '"' + 
    // ' And Classstudyingid = "' + this.class_studying_id+ '"' +
    // ' And ClassSection = "' + this.class_section + '"';

    // return this.sqliteDB.getDataLocalDB(query).then(data => {
    //     this.getstudentData();  // From Server
    // });
  }


  addSdntChange(event) {

    console.log("add sdnt event=", event);
    //   component: IonicSelectableComponent,
    //   value: any
    // }) {
    console.log(event.value.length);
    let sdntarraylist = [];
    let newDate = moment(new Date()).format('YYYY-MM-DD');

    for (var i = 0; i < event.value.length; i++) {
      let sdntarray = {
        "IndxID": event.value[i].HlthIndexId,
        "ScreeningDate":newDate,
        "ScrenerId":this.usersessionService.emis_username(),
        "StuId": event.value[i].student_id,
        "pmoa": 2,
        "rbsk": 0,
        "mentalHealth": 0,
        "dentalSpeciallist": 0, 
        "cwsn": 0,
        "AcYear": "2023-24",
        "AddedStud":event.value[i].HlthIndexId?2:1
      }

      this.searchData.push(sdntarray);
      sdntarraylist.push(sdntarray);
    }
    let obj = {
      "StudDetails": sdntarraylist,
      "HealthDetails": []
    };
    this.pmoaService.HealthScrnSave(obj).subscribe((res) => {
      this.getstudentData();
    },error=>{
      this.alertService.warning("Unable to add students");
    });
   
    // return
    // sdntarraylist.forEach(key => {
    //   this.saveStudentLocalDB(key);
    // });
    // setTimeout(() => {
    //   this.getAddStudentsList();
    // }, 100)
  }

  answerPageNavigate(data) { 
    let obj = { "class_studying_id": this.class_studying_id, "class_section": this.class_section, "SchoolId": this.SchoolId, "data": "added" };
    if(data.pmoa==1){
      this.router.navigate(['/tabs/health-check-up-answer'], { queryParams: { 'SchlId': data.school_id, 'studentid': data.student_id, 'Sectn': data.class_section, 'ClsID': data.class_studying_id,'pageId': 1, "Gender":data.Gender?data.Gender:1,"studentname":data.name,"UniqId":data.UserId,"module":'PMOA', navigate: JSON.stringify(obj),navigateUrl:'/tabs/student-list'
      }, skipLocationChange: false });
    }else {
     this.alertService.warning('Not a referred student');
    }
  }

} 